// Consolidate every Microlink output into one clean report record.
const cfg = $('Config').first().json;
const extract = $('Microlink - Extract').first().json?.data ?? {};
const insights = $('Microlink - Insights').first().json?.data?.insights ?? {};
const cats = insights.lighthouse?.categories ?? {};
// Lighthouse scores arrive as 0-1 floats under categories.<name>.score; normalize to 0-100.
const score = (c) => (typeof c?.score === 'number' ? Math.round(c.score * 100) : null);
const md = $('Microlink - Markdown').first().json?.data ?? '';

const report = {
  url: cfg.url,
  fetchedAt: new Date().toISOString(),
  title: extract.title ?? null,
  description: extract.description ?? null,
  author: extract.author ?? null,
  publisher: extract.publisher ?? null,
  date: extract.date ?? null,
  lang: extract.lang ?? null,
  image: extract.image?.url ?? null,
  logo: extract.logo?.url ?? null,
  lighthouse: {
    performance: score(cats.performance),
    accessibility: score(cats.accessibility),
    bestPractices: score(cats['best-practices']),
    seo: score(cats.seo),
  },
  technologies: Array.isArray(insights.technologies)
    ? insights.technologies.map((t) => t?.name ?? t).slice(0, 20)
    : [],
  markdownExcerpt: typeof md === 'string' ? md.slice(0, 10000) : '',
};

// Carry the screenshot + PDF binaries into the final item.
const binary = {};
const shot = $('Microlink - Screenshot').first().binary;
if (shot) Object.assign(binary, shot);
const pdf = $('Microlink - PDF').first().binary;
if (pdf) Object.assign(binary, pdf);

return [{ json: report, binary }];
